84|static void *
85|xmlFuzzRealloc(void *ptr, size_t size) {
86|    if (fuzzMaxAllocs > 0) {
87|        fuzzNumAllocs += 1;
88|        if (fuzzNumAllocs == fuzzMaxAllocs) {
89|#if XML_FUZZ_MALLOC_ABORT
90|            abort();
91|#endif
92|            fuzzAllocFailed = 1;
93|            return(NULL);
94|        }
95|    }
96|    return realloc(ptr, size);
