132|static int
133|xmlVUpdateError(xmlError *err,
134|                void *ctxt, xmlNodePtr node,
135|                int domain, int code, xmlErrorLevel level,
136|                const char *file, int line,
137|                const char *str1, const char *str2, const char *str3,
138|                int int1, int col,
