143|    /*
144|     * Find first element parent.
145|     */
146|    if (node != NULL) {
147|        int i;
148|
149|        for (i = 0; i < 10; i++) {
150|            if ((node->type == XML_ELEMENT_NODE) ||
151|                (node->parent == NULL))
152|                break;
153|            node = node->parent;
154|        }
155|    }
156|
157|    /*
158|     * Get file and line from node.
159|     */
160|    if (node != NULL) {
161|        if ((file == NULL) && (node->doc != NULL))
162|            file = (const char *) node->doc->URL;
