27|static int
28|xmlVSetError(xmlError *err,
29|             void *ctxt, xmlNodePtr node,
30|             int domain, int code, xmlErrorLevel level,
31|             const char *file, int line,
32|             const char *str1, const char *str2, const char *str3,
33|             int int1, int col,
34|             const char *fmt, va_list ap)
35|{
36|    char *message = NULL;
37|    char *fileCopy = NULL;
38|    char *str1Copy = NULL;
39|    char *str2Copy = NULL;
40|    char *str3Copy = NULL;
41|
42|    if (code == XML_ERR_OK) {
43|        xmlResetError(err);
44|        return(0);
45|    }
46|
47|    /*
48|     * Formatting the message
49|     */
50|    if (fmt == NULL) {
51|        message = xmlMemStrdup("No error message provided");
52|    } else {
53|        xmlChar *tmp;
54|        int res;
55|
56|        res = xmlStrVASPrintf(&tmp, MAX_ERR_MSG_SIZE, fmt, ap);
57|        if (res < 0)
58|            goto err_memory;
59|        message = (char *) tmp;
60|    }
61|    if (message == NULL)
62|        goto err_memory;
63|
64|    if (file != NULL) {
65|        fileCopy = (char *) xmlStrdup((const xmlChar *) file);
66|        if (fileCopy == NULL)
67|            goto err_memory;
68|    }
69|    if (str1 != NULL) {
70|        str1Copy = (char *) xmlStrdup((const xmlChar *) str1);
71|        if (str1Copy == NULL)
72|            goto err_memory;
73|    }
74|    if (str2 != NULL) {
75|        str2Copy = (char *) xmlStrdup((const xmlChar *) str2);
76|        if (str2Copy == NULL)
77|            goto err_memory;
78|    }
79|    if (str3 != NULL) {
80|        str3Copy = (char *) xmlStrdup((const xmlChar *) str3);
81|        if (str3Copy == NULL)
82|            goto err_memory;
83|    }
84|
85|    xmlResetError(err);
86|
87|    err->domain = domain;
88|    err->code = code;
89|    err->message = message;
90|    err->level = level;
91|    err->file = fileCopy;
92|    err->line = line;
93|    err->str1 = str1Copy;
94|    err->str2 = str2Copy;
95|    err->str3 = str3Copy;
96|    err->int1 = int1;
97|    err->int2 = col;
98|    err->node = node;
99|    err->ctxt = ctxt;
100|
101|    return(0);
102|
103|err_memory:
104|    xmlFree(message);
105|    xmlFree(fileCopy);
106|    xmlFree(str1Copy);
107|    xmlFree(str2Copy);
108|    xmlFree(str3Copy);
109|    return(-1);
110|}
