112|static int LIBXML_ATTR_FORMAT(14,15)
113|xmlSetError(xmlError *err,
114|            void *ctxt, xmlNodePtr node,
115|            int domain, int code, xmlErrorLevel level,
116|            const char *file, int line,
117|            const char *str1, const char *str2, const char *str3,
118|            int int1, int col,
119|            const char *fmt, ...)
120|{
121|    va_list ap;
122|    int res;
123|
124|    va_start(ap, fmt);
125|    res = xmlVSetError(err, ctxt, node, domain, code, level, file, line,
126|                       str1, str2, str3, int1, col, fmt, ap);
