132|static int
133|xmlVUpdateError(xmlError *err,
134|                void *ctxt, xmlNodePtr node,
135|                int domain, int code, xmlErrorLevel level,
136|                const char *file, int line,
137|                const char *str1, const char *str2, const char *str3,
138|                int int1, int col,
139|                const char *fmt, va_list ap)
140|{
141|    int res;
142|
143|    /*
144|     * Find first element parent.
145|     */
146|    if (node != NULL) {
147|        int i;
148|
149|        for (i = 0; i < 10; i++) {
150|            if ((node->type == XML_ELEMENT_NODE) ||
151|                (node->parent == NULL))
152|                break;
153|            node = node->parent;
154|        }
155|    }
156|
157|    /*
158|     * Get file and line from node.
159|     */
160|    if (node != NULL) {
161|        if ((file == NULL) && (node->doc != NULL))
162|            file = (const char *) node->doc->URL;
163|
164|        if (line == 0) {
165|            if (node->type == XML_ELEMENT_NODE)
166|                line = node->line;
167|            if ((line == 0) || (line == 65535))
168|                line = xmlGetLineNo(node);
169|        }
170|    }
171|
172|    res = xmlVSetError(err, ctxt, node, domain, code, level, file, line,
173|                       str1, str2, str3, int1, col, fmt, ap);
174|
175|    return(res);
