222|/**
223| * xmlSetGenericErrorFunc:
224| * @ctx:  the new error handling context
225| * @handler:  the new handler function
226| *
227| * Function to reset the handler and the error context for out of
228| * context error messages.
229| * This simply means that @handler will be called for subsequent
230| * error messages while not parsing nor validating. And @ctx will
231| * be passed as first argument to @handler
232| * One can simply force messages to be emitted to another FILE * than
233| * stderr by setting @ctx to this file handle and @handler to NULL.
234| * For multi-threaded applications, this must be set separately for each thread.
235| */
236|void
237|xmlSetGenericErrorFunc(void *ctx, xmlGenericErrorFunc handler) {
238|    xmlGenericErrorContext = ctx;
