289|/**
290| * xmlParserPrintFileContextInternal:
291| * @input:  an xmlParserInputPtr input
292| *
293| * Displays current context within the input content for error tracking
294| */
295|
296|static void
297|xmlParserPrintFileContextInternal(xmlParserInputPtr input ,
298|		xmlGenericErrorFunc channel, void *data ) {
299|    const xmlChar *cur, *base, *start;
300|    unsigned int n, col;	/* GCC warns if signed, because compared with sizeof() */
301|    xmlChar  content[81]; /* space for 80 chars + line terminator */
302|    xmlChar *ctnt;
303|
304|    if ((input == NULL) || (input->cur == NULL))
305|        return;
306|
307|    cur = input->cur;
308|    base = input->base;
309|    /* skip backwards over any end-of-lines */
310|    while ((cur > base) && ((*(cur) == '\n') || (*(cur) == '\r'))) {
311|	cur--;
312|    }
313|    n = 0;
314|    /* search backwards for beginning-of-line (to max buff size) */
315|    while ((n < sizeof(content) - 1) && (cur > base) &&
316|	   (*cur != '\n') && (*cur != '\r')) {
317|        cur--;
318|        n++;
319|    }
320|    if ((n > 0) && ((*cur == '\n') || (*cur == '\r'))) {
321|        cur++;
322|    } else {
323|        /* skip over continuation bytes */
324|        while ((cur < input->cur) && ((*cur & 0xC0) == 0x80))
325|            cur++;
326|    }
327|    /* calculate the error position in terms of the current position */
328|    col = input->cur - cur;
329|    /* search forward for end-of-line (to max buff size) */
330|    n = 0;
331|    start = cur;
332|    /* copy selected text to our buffer */
333|    while ((*cur != 0) && (*(cur) != '\n') && (*(cur) != '\r')) {
334|        int len = input->end - cur;
335|        int c = xmlGetUTF8Char(cur, &len);
336|
337|        if ((c < 0) || (n + len > sizeof(content)-1))
338|            break;
339|        cur += len;
340|	n += len;
341|    }
342|    memcpy(content, start, n);
343|    content[n] = 0;
344|    /* print out the selected text */
345|    channel(data ,"%s\n", content);
346|    /* create blank line with problem pointer */
347|    n = 0;
348|    ctnt = content;
349|    /* (leave buffer space for pointer + line terminator) */
350|    while ((n<col) && (n++ < sizeof(content)-2) && (*ctnt != 0)) {
351|	if (*(ctnt) != '\t')
352|	    *(ctnt) = ' ';
353|	ctnt++;
354|    }
355|    *ctnt++ = '^';
356|    *ctnt = 0;
357|    channel(data ,"%s\n", content);
358|}
