570|/**
571| * xmlRaiseMemoryError:
572| * @schannel: the structured callback channel
573| * @channel: the old callback channel
574| * @data: the callback data
575| * @domain: the domain for the error
576| * @error: optional error struct to be filled
577| *
578| * Update the global and optional error structure, then forward the
579| * error to an error handler.
580| *
581| * This function doesn't make memory allocations which are likely
582| * to fail after an OOM error.
583| */
584|void
585|xmlRaiseMemoryError(xmlStructuredErrorFunc schannel, xmlGenericErrorFunc channel,
586|                    void *data, int domain, xmlError *error)
587|{
588|    xmlError *lastError = &xmlLastError;
589|
590|    xmlResetLastError();
591|    lastError->domain = domain;
592|    lastError->code = XML_ERR_NO_MEMORY;
593|    lastError->level = XML_ERR_FATAL;
594|
595|    if (error != NULL) {
596|        xmlResetError(error);
597|        error->domain = domain;
598|        error->code = XML_ERR_NO_MEMORY;
599|        error->level = XML_ERR_FATAL;
600|    }
601|
602|    if (schannel != NULL) {
603|        schannel(data, lastError);
604|    } else if (xmlStructuredError != NULL) {
605|        xmlStructuredError(xmlStructuredErrorContext, lastError);
606|    } else if (channel != NULL) {
607|        channel(data, "libxml2: out of memory\n");
608|    }
609|}
