116|#ifdef LIBXML_XPTR_LOCS_ENABLED
117|/* xmlXPtrAdvanceNode is a private function, but used by xinclude.c */
118|xmlNodePtr xmlXPtrAdvanceNode(xmlNodePtr cur, int *level);
119|/**
120| * xmlXPtrGetArity:
121| * @cur:  the node
122| *
123| * Returns the number of child for an element, -1 in case of error
124| */
125|static int
126|xmlXPtrGetArity(xmlNodePtr cur) {
127|    int i;
128|    if ((cur == NULL) || (cur->type == XML_NAMESPACE_DECL))
129|	return(-1);
130|    cur = cur->children;
131|    for (i = 0;cur != NULL;cur = cur->next) {
132|	if ((cur->type == XML_ELEMENT_NODE) ||
133|	    (cur->type == XML_DOCUMENT_NODE) ||
134|	    (cur->type == XML_HTML_DOCUMENT_NODE)) {
135|	    i++;
136|	}
137|    }
138|    return(i);
139|}
140|
141|/**
142| * xmlXPtrGetIndex:
143| * @cur:  the node
144| *
145| * Returns the index of the node in its parent children list, -1
146| *         in case of error
147| */
148|static int
149|xmlXPtrGetIndex(xmlNodePtr cur) {
150|    int i;
151|    if ((cur == NULL) || (cur->type == XML_NAMESPACE_DECL))
152|	return(-1);
153|    for (i = 1;cur != NULL;cur = cur->prev) {
154|	if ((cur->type == XML_ELEMENT_NODE) ||
155|	    (cur->type == XML_DOCUMENT_NODE) ||
156|	    (cur->type == XML_HTML_DOCUMENT_NODE)) {
157|	    i++;
158|	}
159|    }
160|    return(i);
161|}
162|#endif /* LIBXML_XPTR_LOCS_ENABLED */
