269|/**
270| * xmlXPtrRangeCheckOrder:
271| * @range:  an object range
272| *
273| * Make sure the points in the range are in the right order
274| */
275|static void
276|xmlXPtrRangeCheckOrder(xmlXPathObjectPtr range) {
277|    int tmp;
278|    xmlNodePtr tmp2;
279|    if (range == NULL)
280|	return;
281|    if (range->type != XPATH_RANGE)
282|	return;
283|    if (range->user2 == NULL)
284|	return;
285|    tmp = xmlXPtrCmpPoints(range->user, range->index,
286|	                     range->user2, range->index2);
287|    if (tmp == -1) {
288|	tmp2 = range->user;
289|	range->user = range->user2;
290|	range->user2 = tmp2;
291|	tmp = range->index;
292|	range->index = range->index2;
293|	range->index2 = tmp;
294|    }
295|}
