583|    if (val != NULL) {
584|        ret->locTab = (xmlXPathObjectPtr *) xmlMalloc(XML_RANGESET_DEFAULT *
585|					     sizeof(xmlXPathObjectPtr));
586|	if (ret->locTab == NULL) {
587|	    xmlXPtrErrMemory("allocating locationset");
588|	    xmlFree(ret);
589|	    return(NULL);
