905|/**
906| * xmlXPtrEvalXPtrPart:
907| * @ctxt:  the XPointer Parser context
908| * @name:  the preparsed Scheme for the XPtrPart
909| *
910| * XPtrPart ::= 'xpointer' '(' XPtrExpr ')'
911| *            | Scheme '(' SchemeSpecificExpr ')'
912| *
913| * Scheme   ::=  NCName - 'xpointer' [VC: Non-XPointer schemes]
914| *
915| * SchemeSpecificExpr ::= StringWithBalancedParens
916| *
917| * StringWithBalancedParens ::=
918| *              [^()]* ('(' StringWithBalancedParens ')' [^()]*)*
919| *              [VC: Parenthesis escaping]
920| *
921| * XPtrExpr ::= Expr [VC: Parenthesis escaping]
922| *
923| * VC: Parenthesis escaping:
924| *   The end of an XPointer part is signaled by the right parenthesis ")"
925| *   character that is balanced with the left parenthesis "(" character
926| *   that began the part. Any unbalanced parenthesis character inside the
927| *   expression, even within literals, must be escaped with a circumflex (^)
928| *   character preceding it. If the expression contains any literal
929| *   occurrences of the circumflex, each must be escaped with an additional
930| *   circumflex (that is, ^^). If the unescaped parentheses in the expression
931| *   are not balanced, a syntax error results.
932| *
933| * Parse and evaluate an XPtrPart. Basically it generates the unescaped
934| * string and if the scheme is 'xpointer' it will call the XPath interpreter.
935| *
936| * TODO: there is no new scheme registration mechanism
937| */
938|
939|static void
940|xmlXPtrEvalXPtrPart(xmlXPathParserContextPtr ctxt, xmlChar *name) {
941|    xmlChar *buffer, *cur;
942|    int len;
943|    int level;
944|
945|    if (name == NULL)
946|    name = xmlXPathParseName(ctxt);
947|    if (name == NULL)
948|	XP_ERROR(XPATH_EXPR_ERROR);
949|
950|    if (CUR != '(') {
951|        xmlFree(name);
952|	XP_ERROR(XPATH_EXPR_ERROR);
953|    }
954|    NEXT;
955|    level = 1;
956|
957|    len = xmlStrlen(ctxt->cur);
958|    len++;
959|    buffer = (xmlChar *) xmlMallocAtomic(len);
960|    if (buffer == NULL) {
961|        xmlXPathPErrMemory(ctxt);
962|        xmlFree(name);
963|	return;
964|    }
965|
966|    cur = buffer;
967|    while (CUR != 0) {
968|	if (CUR == ')') {
969|	    level--;
970|	    if (level == 0) {
971|		NEXT;
972|		break;
973|	    }
974|	} else if (CUR == '(') {
975|	    level++;
976|	} else if (CUR == '^') {
977|            if ((NXT(1) == ')') || (NXT(1) == '(') || (NXT(1) == '^')) {
978|                NEXT;
979|            }
980|	}
981|        *cur++ = CUR;
982|	NEXT;
983|    }
984|    *cur = 0;
985|
986|    if ((level != 0) && (CUR == 0)) {
987|        xmlFree(name);
988|	xmlFree(buffer);
989|	XP_ERROR(XPTR_SYNTAX_ERROR);
990|    }
991|
992|    if (xmlStrEqual(name, (xmlChar *) "xpointer") ||
993|        xmlStrEqual(name, (xmlChar *) "xpath1")) {
994|	const xmlChar *oldBase = ctxt->base;
995|	const xmlChar *oldCur = ctxt->cur;
996|
997|	ctxt->cur = ctxt->base = buffer;
998|	/*
