1075|/**
1076| * xmlXPtrEvalFullXPtr:
1077| * @ctxt:  the XPointer Parser context
1078| * @name:  the preparsed Scheme for the first XPtrPart
1079| *
1080| * FullXPtr ::= XPtrPart (S? XPtrPart)*
1081| *
1082| * As the specs says:
1083| * -----------
1084| * When multiple XPtrParts are provided, they must be evaluated in
1085| * left-to-right order. If evaluation of one part fails, the nexti
1086| * is evaluated. The following conditions cause XPointer part failure:
1087| *
1088| * - An unknown scheme
1089| * - A scheme that does not locate any sub-resource present in the resource
1090| * - A scheme that is not applicable to the media type of the resource
1091| *
1092| * The XPointer application must consume a failed XPointer part and
1093| * attempt to evaluate the next one, if any. The result of the first
1094| * XPointer part whose evaluation succeeds is taken to be the fragment
1095| * located by the XPointer as a whole. If all the parts fail, the result
1096| * for the XPointer as a whole is a sub-resource error.
1097| * -----------
1098| *
1099| * Parse and evaluate a Full XPtr i.e. possibly a cascade of XPath based
1100| * expressions or other schemes.
1101| */
1102|static void
1103|xmlXPtrEvalFullXPtr(xmlXPathParserContextPtr ctxt, xmlChar *name) {
1104|    if (name == NULL)
1105|    name = xmlXPathParseName(ctxt);
1106|    if (name == NULL)
1107|	XP_ERROR(XPATH_EXPR_ERROR);
1108|    while (name != NULL) {
1109|	ctxt->error = XPATH_EXPRESSION_OK;
1110|	xmlXPtrEvalXPtrPart(ctxt, name);
1111|
1112|	/* in case of syntax error, break here */
1113|	if ((ctxt->error != XPATH_EXPRESSION_OK) &&
1114|            (ctxt->error != XML_XPTR_UNKNOWN_SCHEME))
1115|	    return;
1116|
1117|	/*
1118|	 * If the returned value is a non-empty nodeset
1119|	 * or location set, return here.
1120|	 */
1121|	if (ctxt->value != NULL) {
1122|	    xmlXPathObjectPtr obj = ctxt->value;
1123|
1124|	    switch (obj->type) {
1125|#ifdef LIBXML_XPTR_LOCS_ENABLED
1126|		case XPATH_LOCATIONSET: {
1127|		    xmlLocationSetPtr loc = ctxt->value->user;
1128|		    if ((loc != NULL) && (loc->locNr > 0))
1129|			return;
1130|		    break;
1131|		}
1132|#endif
1133|		case XPATH_NODESET: {
1134|		    xmlNodeSetPtr loc = ctxt->value->nodesetval;
1135|		    if ((loc != NULL) && (loc->nodeNr > 0))
1136|			return;
1137|		    break;
1138|		}
1139|		default:
1140|		    break;
1141|	    }
1142|
1143|	    /*
1144|	     * Evaluating to improper values is equivalent to
1145|	     * a sub-resource error, clean-up the stack
1146|	     */
1147|	    do {
1148|		obj = valuePop(ctxt);
1149|		if (obj != NULL) {
1150|		    xmlXPathFreeObject(obj);
1151|		}
1152|	    } while (obj != NULL);
1153|	}
1154|
1155|	/*
1156|	 * Is there another XPointer part.
1157|	 */
1158|	SKIP_BLANKS;
1159|	name = xmlXPathParseName(ctxt);
1160|    }
1161|}
1162|
1163|/**
1164| * xmlXPtrEvalChildSeq:
1165| * @ctxt:  the XPointer Parser context
1166| * @name:  a possible ID name of the child sequence
1167| *
1168| *  ChildSeq ::= '/1' ('/' [0-9]*)*
1169| *             | Name ('/' [0-9]*)+
1170| *
1171| * Parse and evaluate a Child Sequence. This routine also handle the
1172| * case of a Bare Name used to get a document ID.
1173| */
1174|static void
1175|xmlXPtrEvalChildSeq(xmlXPathParserContextPtr ctxt, xmlChar *name) {
1176|    /*
1177|     * XPointer don't allow by syntax to address in multirooted trees
1178|     * this might prove useful in some cases, warn about it.
1179|     */
1180|    if ((name == NULL) && (CUR == '/') && (NXT(1) != '1')) {
1181|        xmlXPtrErr(ctxt, XML_XPTR_CHILDSEQ_START,
1182|		   "warning: ChildSeq not starting by /1\n", NULL);
1183|    }
1184|
1185|    if (name != NULL) {
1186|	valuePush(ctxt, xmlXPathNewString(name));
1187|	xmlFree(name);
1188|	xmlXPathIdFunction(ctxt, 1);
1189|	CHECK_ERROR;
1190|    }
1191|
1192|    while (CUR == '/') {
1193|	int child = 0, overflow = 0;
1194|	NEXT;
1195|
1196|	while ((CUR >= '0') && (CUR <= '9')) {
1197|            int d = CUR - '0';
1198|            if (child > INT_MAX / 10)
1199|                overflow = 1;
1200|            else
1201|                child *= 10;
1202|            if (child > INT_MAX - d)
1203|                overflow = 1;
1204|            else
1205|                child += d;
1206|	    NEXT;
1207|	}
1208|        if (overflow)
1209|            child = 0;
1210|	xmlXPtrGetChildNo(ctxt, child);
1211|    }
1212|}
