1215|/**
1216| * xmlXPtrEvalXPointer:
1217| * @ctxt:  the XPointer Parser context
1218| *
1219| *  XPointer ::= Name
1220| *             | ChildSeq
1221| *             | FullXPtr
1222| *
1223| * Parse and evaluate an XPointer
1224| */
1225|static void
1226|xmlXPtrEvalXPointer(xmlXPathParserContextPtr ctxt) {
1227|    if (ctxt->valueTab == NULL) {
1228|	/* Allocate the value stack */
1229|	ctxt->valueTab = (xmlXPathObjectPtr *)
1230|			 xmlMalloc(10 * sizeof(xmlXPathObjectPtr));
1231|	if (ctxt->valueTab == NULL) {
1232|	    xmlXPathPErrMemory(ctxt);
1233|	    return;
1234|	}
1235|	ctxt->valueNr = 0;
1236|	ctxt->valueMax = 10;
1237|	ctxt->value = NULL;
1238|    }
1239|    SKIP_BLANKS;
1240|    if (CUR == '/') {
1241|	xmlXPathRoot(ctxt);
1242|        xmlXPtrEvalChildSeq(ctxt, NULL);
1243|    } else {
1244|	xmlChar *name;
1245|
1246|	name = xmlXPathParseName(ctxt);
1247|	if (name == NULL)
1248|	    XP_ERROR(XPATH_EXPR_ERROR);
1249|	if (CUR == '(') {
1250|	    xmlXPtrEvalFullXPtr(ctxt, name);
1251|	    /* Short evaluation */
1252|	    return;
1253|	} else {
1254|	    /* this handle both Bare Names and Child Sequences */
1255|	    xmlXPtrEvalChildSeq(ctxt, name);
1256|	}
1257|    }
1258|    SKIP_BLANKS;
1259|    if (CUR != 0)
1260|	XP_ERROR(XPATH_EXPR_ERROR);
1261|}
