1331|/**
1332| * xmlXPtrEval:
1333| * @str:  the XPointer expression
1334| * @ctx:  the XPointer context
1335| *
1336| * Evaluate the XPath Location Path in the given context.
1337| *
1338| * Returns the xmlXPathObjectPtr resulting from the evaluation or NULL.
1339| *         the caller has to free the object.
1340| */
1341|xmlXPathObjectPtr
1342|xmlXPtrEval(const xmlChar *str, xmlXPathContextPtr ctx) {
1343|    xmlXPathParserContextPtr ctxt;
1344|    xmlXPathObjectPtr res = NULL, tmp;
1345|    xmlXPathObjectPtr init = NULL;
1346|    int stack = 0;
1347|
1348|    xmlInitParser();
1349|
1350|    if ((ctx == NULL) || (str == NULL))
1351|	return(NULL);
1352|
1353|    xmlResetError(&ctx->lastError);
1354|
1355|    ctxt = xmlXPathNewParserContext(str, ctx);
1356|    if (ctxt == NULL) {
1357|        xmlXPathErrMemory(ctx);
1358|	return(NULL);
1359|    }
1360|    xmlXPtrEvalXPointer(ctxt);
1361|    if (ctx->lastError.code != XML_ERR_OK)
1362|        goto error;
1363|
1364|    if ((ctxt->value != NULL) &&
1365|#ifdef LIBXML_XPTR_LOCS_ENABLED
1366|	(ctxt->value->type != XPATH_LOCATIONSET) &&
1367|#endif
1368|	(ctxt->value->type != XPATH_NODESET)) {
1369|        xmlXPtrErr(ctxt, XML_XPTR_EVAL_FAILED,
1370|		"xmlXPtrEval: evaluation failed to return a node set\n",
1371|		   NULL);
1372|    } else {
1373|	res = valuePop(ctxt);
1374|    }
1375|
1376|    do {
1377|        tmp = valuePop(ctxt);
1378|	if (tmp != NULL) {
1379|	    if (tmp != init) {
1380|		if (tmp->type == XPATH_NODESET) {
1381|		    /*
1382|		     * Evaluation may push a root nodeset which is unused
1383|		     */
1384|		    xmlNodeSetPtr set;
1385|		    set = tmp->nodesetval;
1386|		    if ((set == NULL) || (set->nodeNr != 1) ||
1387|			(set->nodeTab[0] != (xmlNodePtr) ctx->doc))
1388|			stack++;
1389|		} else
1390|		    stack++;
1391|	    }
1392|	    xmlXPathFreeObject(tmp);
1393|        }
1394|    } while (tmp != NULL);
1395|    if (stack != 0) {
1396|        xmlXPtrErr(ctxt, XML_XPTR_EXTRA_OBJECTS,
1397|		   "xmlXPtrEval: object(s) left on the eval stack\n",
1398|		   NULL);
1399|    }
1400|    if (ctx->lastError.code != XML_ERR_OK) {
1401|	xmlXPathFreeObject(res);
1402|	res = NULL;
1403|    }
1404|
1405|error:
1406|    xmlXPathFreeParserContext(ctxt);
1407|    return(res);
1408|}
