1410|#ifdef LIBXML_XPTR_LOCS_ENABLED
1411|/**
1412| * xmlXPtrBuildRangeNodeList:
1413| * @range:  a range object
1414| *
1415| * Build a node list tree copy of the range
1416| *
1417| * Returns an xmlNodePtr list or NULL.
1418| *         the caller has to free the node tree.
1419| */
1420|static xmlNodePtr
1421|xmlXPtrBuildRangeNodeList(xmlXPathObjectPtr range) {
1422|    /* pointers to generated nodes */
1423|    xmlNodePtr list = NULL, last = NULL, parent = NULL, tmp;
1424|    /* pointers to traversal nodes */
1425|    xmlNodePtr start, cur, end;
1426|    int index1, index2;
1427|
1428|    if (range == NULL)
1429|	return(NULL);
1430|    if (range->type != XPATH_RANGE)
1431|	return(NULL);
1432|    start = (xmlNodePtr) range->user;
1433|
1434|    if ((start == NULL) || (start->type == XML_NAMESPACE_DECL))
1435|	return(NULL);
1436|    end = range->user2;
1437|    if (end == NULL)
1438|	return(xmlCopyNode(start, 1));
1439|    if (end->type == XML_NAMESPACE_DECL)
1440|        return(NULL);
1441|
1442|    cur = start;
1443|    index1 = range->index;
1444|    index2 = range->index2;
1445|    while (cur != NULL) {
1446|	if (cur == end) {
1447|	    if (cur->type == XML_TEXT_NODE) {
1448|		const xmlChar *content = cur->content;
1449|		int len;
1450|
1451|		if (content == NULL) {
1452|		    tmp = xmlNewTextLen(NULL, 0);
1453|		} else {
1454|		    len = index2;
1455|		    if ((cur == start) && (index1 > 1)) {
1456|			content += (index1 - 1);
1457|			len -= (index1 - 1);
1458|			index1 = 0;
1459|		    } else {
1460|			len = index2;
1461|		    }
1462|		    tmp = xmlNewTextLen(content, len);
1463|		}
1464|		/* single sub text node selection */
1465|		if (list == NULL)
1466|		    return(tmp);
1467|		/* prune and return full set */
1468|		if (last != NULL)
1469|		    xmlAddNextSibling(last, tmp);
1470|		else
1471|		    xmlAddChild(parent, tmp);
1472|		return(list);
1473|	    } else {
1474|		tmp = xmlCopyNode(cur, 0);
1475|		if (list == NULL) {
1476|		    list = tmp;
1477|		    parent = tmp;
1478|		} else {
1479|		    if (last != NULL)
1480|			parent = xmlAddNextSibling(last, tmp);
1481|		    else
1482|			parent = xmlAddChild(parent, tmp);
1483|		}
1484|		last = NULL;
1485|
1486|		if (index2 > 1) {
1487|		    end = xmlXPtrGetNthChild(cur, index2 - 1);
1488|		    index2 = 0;
1489|		}
1490|		if ((cur == start) && (index1 > 1)) {
1491|		    cur = xmlXPtrGetNthChild(cur, index1 - 1);
1492|		    index1 = 0;
1493|		} else {
1494|		    cur = cur->children;
1495|		}
1496|		/*
1497|		 * Now gather the remaining nodes from cur to end
1498|		 */
1499|		continue; /* while */
1500|	    }
1501|	} else if ((cur == start) &&
1502|		   (list == NULL) /* looks superfluous but ... */ ) {
1503|	    if ((cur->type == XML_TEXT_NODE) ||
1504|		(cur->type == XML_CDATA_SECTION_NODE)) {
1505|		const xmlChar *content = cur->content;
1506|
1507|		if (content == NULL) {
1508|		    tmp = xmlNewTextLen(NULL, 0);
1509|		} else {
1510|		    if (index1 > 1) {
1511|			content += (index1 - 1);
1512|		    }
1513|		    tmp = xmlNewText(content);
1514|		}
1515|		last = list = tmp;
1516|	    } else {
1517|		if ((cur == start) && (index1 > 1)) {
1518|		    tmp = xmlCopyNode(cur, 0);
1519|		    list = tmp;
1520|		    parent = tmp;
1521|		    last = NULL;
1522|		    cur = xmlXPtrGetNthChild(cur, index1 - 1);
1523|		    index1 = 0;
1524|		    /*
1525|		     * Now gather the remaining nodes from cur to end
1526|		     */
1527|		    continue; /* while */
1528|		}
1529|		tmp = xmlCopyNode(cur, 1);
1530|		list = tmp;
1531|		parent = NULL;
1532|		last = tmp;
1533|	    }
1534|	} else {
1535|	    tmp = NULL;
1536|	    switch (cur->type) {
1537|		case XML_DTD_NODE:
1538|		case XML_ELEMENT_DECL:
1539|		case XML_ATTRIBUTE_DECL:
1540|		case XML_ENTITY_NODE:
1541|		    /* Do not copy DTD information */
1542|		    break;
1543|		case XML_ENTITY_DECL:
1544|		    /* TODO: handle crossing entities -> stack needed */
1545|		    break;
1546|		case XML_XINCLUDE_START:
1547|		case XML_XINCLUDE_END:
1548|		    /* don't consider it part of the tree content */
1549|		    break;
1550|		case XML_ATTRIBUTE_NODE:
1551|		    /* Humm, should not happen ! */
1552|		    break;
1553|		default:
1554|		    tmp = xmlCopyNode(cur, 1);
1555|		    break;
1556|	    }
1557|	    if (tmp != NULL) {
1558|		if ((list == NULL) || ((last == NULL) && (parent == NULL)))  {
1559|		    return(NULL);
1560|		}
1561|		if (last != NULL)
1562|		    xmlAddNextSibling(last, tmp);
1563|		else {
1564|		    last = xmlAddChild(parent, tmp);
1565|		}
1566|	    }
1567|	}
1568|	/*
1569|	 * Skip to next node in document order
1570|	 */
1571|	if ((list == NULL) || ((last == NULL) && (parent == NULL)))  {
1572|	    return(NULL);
1573|	}
1574|	cur = xmlXPtrAdvanceNode(cur, NULL);
1575|    }
1576|    return(list);
