1627|		}
1628|		if (last == NULL)
1629|		    list = last = xmlCopyNode(set->nodeTab[i], 1);
1630|		else {
1631|		    xmlAddNextSibling(last, xmlCopyNode(set->nodeTab[i], 1));
1632|		    if (last->next != NULL)
