1751| * @nargs:  the number of args
1752| *
1753| * Function implementing start-point() operation
1754| * as described in 5.4.3
1755| * ----------------
1756| * location-set start-point(location-set)
1757| *
1758| * For each location x in the argument location-set, start-point adds a
1759| * location of type point to the result location-set. That point represents
1760| * the start point of location x and is determined by the following rules:
1761| *
1762| * - If x is of type point, the start point is x.
1763| * - If x is of type range, the start point is the start point of x.
1764| * - If x is of type root, element, text, comment, or processing instruction,
1765| * - the container node of the start point is x and the index is 0.
1766| * - If x is of type attribute or namespace, the function must signal a
1767| *   syntax error.
1768| * ----------------
1769| *
1770| */
1771|static void
1772|xmlXPtrStartPointFunction(xmlXPathParserContextPtr ctxt, int nargs) {
1773|    xmlXPathObjectPtr tmp, obj, point;
1774|    xmlLocationSetPtr newset = NULL;
1775|    xmlLocationSetPtr oldset = NULL;
1776|
1777|    CHECK_ARITY(1);
1778|    if ((ctxt->value == NULL) ||
1779|	((ctxt->value->type != XPATH_LOCATIONSET) &&
1780|	 (ctxt->value->type != XPATH_NODESET)))
1781|        XP_ERROR(XPATH_INVALID_TYPE)
1782|
1783|    obj = valuePop(ctxt);
1784|    if (obj->type == XPATH_NODESET) {
1785|	/*
1786|	 * First convert to a location set
1787|	 */
1788|	tmp = xmlXPtrNewLocationSetNodeSet(obj->nodesetval);
1789|	xmlXPathFreeObject(obj);
1790|	if (tmp == NULL)
1791|            XP_ERROR(XPATH_MEMORY_ERROR)
1792|	obj = tmp;
1793|    }
1794|
1795|    newset = xmlXPtrLocationSetCreate(NULL);
1796|    if (newset == NULL) {
1797|	xmlXPathFreeObject(obj);
1798|        XP_ERROR(XPATH_MEMORY_ERROR);
1799|    }
1800|    oldset = (xmlLocationSetPtr) obj->user;
1801|    if (oldset != NULL) {
1802|	int i;
1803|
1804|	for (i = 0; i < oldset->locNr; i++) {
1805|	    tmp = oldset->locTab[i];
1806|	    if (tmp == NULL)
1807|		continue;
1808|	    point = NULL;
1809|	    switch (tmp->type) {
1810|		case XPATH_POINT:
1811|		    point = xmlXPtrNewPoint(tmp->user, tmp->index);
1812|		    break;
1813|		case XPATH_RANGE: {
1814|		    xmlNodePtr node = tmp->user;
1815|		    if (node != NULL) {
1816|			if ((node->type == XML_ATTRIBUTE_NODE) ||
1817|                            (node->type == XML_NAMESPACE_DECL)) {
1818|			    xmlXPathFreeObject(obj);
1819|			    xmlXPtrFreeLocationSet(newset);
1820|			    XP_ERROR(XPTR_SYNTAX_ERROR);
1821|			}
1822|			point = xmlXPtrNewPoint(node, tmp->index);
1823|		    }
1824|		    break;
1825|	        }
1826|		default:
1827|		    /*** Should we raise an error ?
1828|		    xmlXPathFreeObject(obj);
1829|		    xmlXPathFreeObject(newset);
1830|		    XP_ERROR(XPATH_INVALID_TYPE)
1831|		    ***/
1832|		    break;
1833|	    }
1834|            if (point != NULL)
1835|		xmlXPtrLocationSetAdd(newset, point);
1836|	}
1837|    }
1838|    xmlXPathFreeObject(obj);
1839|    valuePush(ctxt, xmlXPtrWrapLocationSet(newset));
