1944| * @ctxt:  the XPointer Parser context
1945| * @loc:  the location for which the covering range must be computed
1946| *
1947| * A covering range is a range that wholly encompasses a location
1948| * Section 5.3.3. Covering Ranges for All Location Types
1949| *        http://www.w3.org/TR/xptr#N2267
1950| *
1951| * Returns a new location or NULL in case of error
1952| */
1953|static xmlXPathObjectPtr
1954|xmlXPtrCoveringRange(xmlXPathParserContextPtr ctxt, xmlXPathObjectPtr loc) {
1955|    if (loc == NULL)
1956|	return(NULL);
1957|    if ((ctxt == NULL) || (ctxt->context == NULL) ||
1958|	(ctxt->context->doc == NULL))
1959|	return(NULL);
1960|    switch (loc->type) {
1961|        case XPATH_POINT:
1962|	    return(xmlXPtrNewRange(loc->user, loc->index,
1963|			           loc->user, loc->index));
1964|        case XPATH_RANGE:
1965|	    if (loc->user2 != NULL) {
1966|		return(xmlXPtrNewRange(loc->user, loc->index,
1967|			              loc->user2, loc->index2));
1968|	    } else {
1969|		xmlNodePtr node = (xmlNodePtr) loc->user;
1970|		if (node == (xmlNodePtr) ctxt->context->doc) {
1971|		    return(xmlXPtrNewRange(node, 0, node,
1972|					   xmlXPtrGetArity(node)));
1973|		} else {
1974|		    switch (node->type) {
1975|			case XML_ATTRIBUTE_NODE:
1976|			/* !!! our model is slightly different than XPath */
1977|			    return(xmlXPtrNewRange(node, 0, node,
1978|					           xmlXPtrGetArity(node)));
1979|			case XML_ELEMENT_NODE:
1980|			case XML_TEXT_NODE:
1981|			case XML_CDATA_SECTION_NODE:
1982|			case XML_ENTITY_REF_NODE:
1983|			case XML_PI_NODE:
1984|			case XML_COMMENT_NODE:
1985|			case XML_DOCUMENT_NODE:
1986|			case XML_NOTATION_NODE:
1987|			case XML_HTML_DOCUMENT_NODE: {
1988|			    int indx = xmlXPtrGetIndex(node);
1989|
1990|			    node = node->parent;
1991|			    return(xmlXPtrNewRange(node, indx - 1,
1992|					           node, indx + 1));
1993|			}
1994|			default:
1995|			    return(NULL);
1996|		    }
1997|		}
1998|	    }
1999|	default:
2000|	    /* TODO: missed one case ??? */
2001|            break;
2002|    }
2003|    return(NULL);
