2868|	    /*
2869|	     * Run the evaluation with a node list made of a single item
2870|	     * in the nodeset.
2871|	     */
2872|	    ctxt->context->node = oldset->locTab[i]->user;
2873|	    tmp = xmlXPathNewNodeSet(ctxt->context->node);
2874|	    valuePush(ctxt, tmp);
2875|	    ctxt->context->contextSize = oldset->locNr;
2876|	    ctxt->context->proximityPosition = i + 1;
2877|
2878|	    xmlXPathEvalExpr(ctxt);
2879|	    CHECK_ERROR;
2880|
2881|	    /*
2882|	     * The result of the evaluation need to be tested to
2883|	     * decided whether the filter succeeded or not
2884|	     */
2885|	    res = valuePop(ctxt);
2886|	    if (xmlXPathEvaluatePredicateResult(ctxt, res)) {
2887|	        xmlXPtrLocationSetAdd(newset,
2888|			xmlXPathObjectCopy(oldset->locTab[i]));
2889|	    }
2890|
2891|	    /*
2892|	     * Cleanup
2893|	     */
2894|	    if (res != NULL)
2895|		xmlXPathFreeObject(res);
2896|	    if (ctxt->value == tmp) {
2897|		res = valuePop(ctxt);
2898|		xmlXPathFreeObject(res);
2899|	    }
2900|
2901|	    ctxt->context->node = NULL;
2902|	}
2903|
2904|	/*
2905|	 * The result is used as the new evaluation set.
2906|	 */
2907|	xmlXPathFreeObject(obj);
2908|	ctxt->context->node = NULL;
2909|	ctxt->context->contextSize = -1;
2910|	ctxt->context->proximityPosition = -1;
2911|	valuePush(ctxt, xmlXPtrWrapLocationSet(newset));
2912|    }
2913|    if (CUR != ']') {
2914|	XP_ERROR(XPATH_INVALID_PREDICATE_ERROR);
2915|    }
2916|
2917|    NEXT;
2918|    SKIP_BLANKS;
2919|}
2920|#endif /* LIBXML_XPTR_LOCS_ENABLED */
