119|/**
120| * xmlXPtrGetArity:
121| * @cur:  the node
122| *
123| * Returns the number of child for an element, -1 in case of error
124| */
125|static int
126|xmlXPtrGetArity(xmlNodePtr cur) {
127|    int i;
128|    if ((cur == NULL) || (cur->type == XML_NAMESPACE_DECL))
129|	return(-1);
130|    cur = cur->children;
131|    for (i = 0;cur != NULL;cur = cur->next) {
132|	if ((cur->type == XML_ELEMENT_NODE) ||
133|	    (cur->type == XML_DOCUMENT_NODE) ||
134|	    (cur->type == XML_HTML_DOCUMENT_NODE)) {
135|	    i++;
136|	}
137|    }
138|    return(i);
