141|/**
142| * xmlXPtrGetIndex:
143| * @cur:  the node
144| *
145| * Returns the index of the node in its parent children list, -1
146| *         in case of error
147| */
148|static int
149|xmlXPtrGetIndex(xmlNodePtr cur) {
150|    int i;
151|    if ((cur == NULL) || (cur->type == XML_NAMESPACE_DECL))
152|	return(-1);
153|    for (i = 1;cur != NULL;cur = cur->prev) {
154|	if ((cur->type == XML_ELEMENT_NODE) ||
155|	    (cur->type == XML_DOCUMENT_NODE) ||
156|	    (cur->type == XML_HTML_DOCUMENT_NODE)) {
157|	    i++;
158|	}
159|    }
160|    return(i);
