181|	    (cur->type == XML_DOCUMENT_NODE) ||
182|	    (cur->type == XML_HTML_DOCUMENT_NODE)) {
183|	    i++;
184|	    if (i == no)
185|		break;
186|	}
187|    }
188|    return(cur);
