838|
839|static void xmlXPtrEvalChildSeq(xmlXPathParserContextPtr ctxt, xmlChar *name);
840|
841|/*
842| * Macros for accessing the content. Those should be used only by the parser,
843| * and not exported.
844| *
845| * Dirty macros, i.e. one need to make assumption on the context to use them
846| *
847| *   CUR     returns the current xmlChar value, i.e. a 8 bit value
848| *           in ISO-Latin or UTF-8.
849| *           This should be used internally by the parser
850| *           only to compare to ASCII values otherwise it would break when
851| *           running with UTF-8 encoding.
852| *   NXT(n)  returns the n'th next xmlChar. Same as CUR is should be used only
853| *           to compare on ASCII based substring.
854| *   SKIP(n) Skip n xmlChar, and must also be used only to skip ASCII defined
855| *           strings within the parser.
856| *   CURRENT Returns the current char value, with the full decoding of
857| *           UTF-8 if we are using this mode. It returns an int.
858| *   NEXT    Skip to the next character, this does the proper decoding
859| *           in UTF-8 mode. It also pop-up unfinished entities on the fly.
860| *           It returns the pointer to the current xmlChar.
861| */
862|
863|#define CUR (*ctxt->cur)
864|#define SKIP(val) ctxt->cur += (val)
865|#define NXT(val) ctxt->cur[(val)]
866|
867|#define SKIP_BLANKS							\
868|    while (IS_BLANK_CH(*(ctxt->cur))) NEXT
869|
870|#define CURRENT (*ctxt->cur)
871|#define NEXT ((*ctxt->cur) ?  ctxt->cur++: ctxt->cur)
872|
873|/*
874| * xmlXPtrGetChildNo:
875| * @ctxt:  the XPointer Parser context
876| * @index:  the child number
877| *
878| * Move the current node of the nodeset on the stack to the
879| * given child if found
880| */
881|static void
882|xmlXPtrGetChildNo(xmlXPathParserContextPtr ctxt, int indx) {
883|    xmlNodePtr cur = NULL;
884|    xmlXPathObjectPtr obj;
885|    xmlNodeSetPtr oldset;
886|
887|    CHECK_TYPE(XPATH_NODESET);
888|    obj = valuePop(ctxt);
889|    oldset = obj->nodesetval;
890|    if ((indx <= 0) || (oldset == NULL) || (oldset->nodeNr != 1)) {
891|	xmlXPathFreeObject(obj);
892|	valuePush(ctxt, xmlXPathNewNodeSet(NULL));
893|	return;
894|    }
895|    cur = xmlXPtrGetNthChild(oldset->nodeTab[0], indx);
896|    if (cur == NULL) {
897|	xmlXPathFreeObject(obj);
898|	valuePush(ctxt, xmlXPathNewNodeSet(NULL));
899|	return;
900|    }
901|    oldset->nodeTab[0] = cur;
902|    valuePush(ctxt, obj);
903|}
