905|/**
906| * xmlXPtrEvalXPtrPart:
907| * @ctxt:  the XPointer Parser context
908| * @name:  the preparsed Scheme for the XPtrPart
909| *
910| * XPtrPart ::= 'xpointer' '(' XPtrExpr ')'
911| *            | Scheme '(' SchemeSpecificExpr ')'
912| *
913| * Scheme   ::=  NCName - 'xpointer' [VC: Non-XPointer schemes]
914| *
915| * SchemeSpecificExpr ::= StringWithBalancedParens
916| *
917| * StringWithBalancedParens ::=
918| *              [^()]* ('(' StringWithBalancedParens ')' [^()]*)*
919| *              [VC: Parenthesis escaping]
920| *
921| * XPtrExpr ::= Expr [VC: Parenthesis escaping]
922| *
923| * VC: Parenthesis escaping:
924| *   The end of an XPointer part is signaled by the right parenthesis ")"
925| *   character that is balanced with the left parenthesis "(" character
926| *   that began the part. Any unbalanced parenthesis character inside the
927| *   expression, even within literals, must be escaped with a circumflex (^)
928| *   character preceding it. If the expression contains any literal
929| *   occurrences of the circumflex, each must be escaped with an additional
930| *   circumflex (that is, ^^). If the unescaped parentheses in the expression
931| *   are not balanced, a syntax error results.
932| *
933| * Parse and evaluate an XPtrPart. Basically it generates the unescaped
934| * string and if the scheme is 'xpointer' it will call the XPath interpreter.
935| *
936| * TODO: there is no new scheme registration mechanism
937| */
938|
939|static void
940|xmlXPtrEvalXPtrPart(xmlXPathParserContextPtr ctxt, xmlChar *name) {
941|    xmlChar *buffer, *cur;
942|    int len;
943|    int level;
944|
945|    if (name == NULL)
946|    name = xmlXPathParseName(ctxt);
947|    if (name == NULL)
948|	XP_ERROR(XPATH_EXPR_ERROR);
949|
950|    if (CUR != '(') {
951|        xmlFree(name);
952|	XP_ERROR(XPATH_EXPR_ERROR);
953|    }
954|    NEXT;
955|    level = 1;
956|
957|    len = xmlStrlen(ctxt->cur);
958|    len++;
959|    buffer = (xmlChar *) xmlMallocAtomic(len);
960|    if (buffer == NULL) {
961|        xmlXPathPErrMemory(ctxt);
962|        xmlFree(name);
963|	return;
964|    }
965|
966|    cur = buffer;
967|    while (CUR != 0) {
968|	if (CUR == ')') {
969|	    level--;
970|	    if (level == 0) {
971|		NEXT;
972|		break;
973|	    }
974|	} else if (CUR == '(') {
975|	    level++;
976|	} else if (CUR == '^') {
977|            if ((NXT(1) == ')') || (NXT(1) == '(') || (NXT(1) == '^')) {
978|                NEXT;
979|            }
980|	}
981|        *cur++ = CUR;
982|	NEXT;
983|    }
984|    *cur = 0;
985|
986|    if ((level != 0) && (CUR == 0)) {
987|        xmlFree(name);
988|	xmlFree(buffer);
989|	XP_ERROR(XPTR_SYNTAX_ERROR);
990|    }
991|
992|    if (xmlStrEqual(name, (xmlChar *) "xpointer") ||
993|        xmlStrEqual(name, (xmlChar *) "xpath1")) {
994|	const xmlChar *oldBase = ctxt->base;
995|	const xmlChar *oldCur = ctxt->cur;
996|
997|	ctxt->cur = ctxt->base = buffer;
998|	/*
999|	 * To evaluate an xpointer scheme element (4.3) we need:
1000|	 *   context initialized to the root
1001|	 *   context position initialized to 1
1002|	 *   context size initialized to 1
1003|	 */
1004|	ctxt->context->node = (xmlNodePtr)ctxt->context->doc;
1005|	ctxt->context->proximityPosition = 1;
1006|	ctxt->context->contextSize = 1;
1007|#ifdef LIBXML_XPTR_LOCS_ENABLED
1008|        ctxt->xptr = xmlStrEqual(name, (xmlChar *) "xpointer");
1009|#endif
1010|	xmlXPathEvalExpr(ctxt);
1011|	ctxt->base = oldBase;
1012|        ctxt->cur = oldCur;
1013|    } else if (xmlStrEqual(name, (xmlChar *) "element")) {
1014|	const xmlChar *oldBase = ctxt->base;
1015|	const xmlChar *oldCur = ctxt->cur;
1016|	xmlChar *name2;
1017|
1018|	ctxt->cur = ctxt->base = buffer;
1019|	if (buffer[0] == '/') {
1020|	    xmlXPathRoot(ctxt);
1021|	    xmlXPtrEvalChildSeq(ctxt, NULL);
1022|	} else {
1023|	    name2 = xmlXPathParseName(ctxt);
1024|	    if (name2 == NULL) {
1025|                ctxt->base = oldBase;
1026|                ctxt->cur = oldCur;
1027|		xmlFree(buffer);
1028|                xmlFree(name);
1029|		XP_ERROR(XPATH_EXPR_ERROR);
1030|	    }
1031|	    xmlXPtrEvalChildSeq(ctxt, name2);
1032|	}
1033|	ctxt->base = oldBase;
1034|        ctxt->cur = oldCur;
1035|#ifdef XPTR_XMLNS_SCHEME
1036|    } else if (xmlStrEqual(name, (xmlChar *) "xmlns")) {
1037|	const xmlChar *oldBase = ctxt->base;
1038|	const xmlChar *oldCur = ctxt->cur;
1039|	xmlChar *prefix;
1040|
1041|	ctxt->cur = ctxt->base = buffer;
1042|        prefix = xmlXPathParseNCName(ctxt);
1043|	if (prefix == NULL) {
1044|            ctxt->base = oldBase;
1045|            ctxt->cur = oldCur;
1046|	    xmlFree(buffer);
1047|	    xmlFree(name);
1048|	    XP_ERROR(XPTR_SYNTAX_ERROR);
1049|	}
1050|	SKIP_BLANKS;
1051|	if (CUR != '=') {
1052|            ctxt->base = oldBase;
1053|            ctxt->cur = oldCur;
1054|	    xmlFree(prefix);
1055|	    xmlFree(buffer);
1056|	    xmlFree(name);
1057|	    XP_ERROR(XPTR_SYNTAX_ERROR);
1058|	}
1059|	NEXT;
1060|	SKIP_BLANKS;
1061|
1062|	xmlXPathRegisterNs(ctxt->context, prefix, ctxt->cur);
1063|        ctxt->base = oldBase;
1064|        ctxt->cur = oldCur;
1065|	xmlFree(prefix);
1066|#endif /* XPTR_XMLNS_SCHEME */
1067|    } else {
1068|        xmlXPtrErr(ctxt, XML_XPTR_UNKNOWN_SCHEME,
1069|		   "unsupported scheme '%s'\n", name);
1070|    }
1071|    xmlFree(buffer);
1072|    xmlFree(name);
1073|}
