1579|/**
1580| * xmlXPtrBuildNodeList:
1581| * @obj:  the XPointer result from the evaluation.
1582| *
1583| * Build a node list tree copy of the XPointer result.
1584| * This will drop Attributes and Namespace declarations.
1585| *
1586| * Returns an xmlNodePtr list or NULL.
1587| *         the caller has to free the node tree.
1588| */
1589|xmlNodePtr
1590|xmlXPtrBuildNodeList(xmlXPathObjectPtr obj) {
1591|    xmlNodePtr list = NULL, last = NULL;
1592|    int i;
1593|
1594|    if (obj == NULL)
1595|	return(NULL);
1596|    switch (obj->type) {
1597|        case XPATH_NODESET: {
1598|	    xmlNodeSetPtr set = obj->nodesetval;
1599|	    if (set == NULL)
1600|		return(NULL);
1601|	    for (i = 0;i < set->nodeNr;i++) {
1602|		if (set->nodeTab[i] == NULL)
1603|		    continue;
1604|		switch (set->nodeTab[i]->type) {
1605|		    case XML_TEXT_NODE:
1606|		    case XML_CDATA_SECTION_NODE:
1607|		    case XML_ELEMENT_NODE:
1608|		    case XML_ENTITY_REF_NODE:
1609|		    case XML_ENTITY_NODE:
1610|		    case XML_PI_NODE:
1611|		    case XML_COMMENT_NODE:
1612|		    case XML_DOCUMENT_NODE:
1613|		    case XML_HTML_DOCUMENT_NODE:
1614|		    case XML_XINCLUDE_START:
1615|		    case XML_XINCLUDE_END:
1616|			break;
1617|		    case XML_ATTRIBUTE_NODE:
1618|		    case XML_NAMESPACE_DECL:
1619|		    case XML_DOCUMENT_TYPE_NODE:
1620|		    case XML_DOCUMENT_FRAG_NODE:
1621|		    case XML_NOTATION_NODE:
1622|		    case XML_DTD_NODE:
1623|		    case XML_ELEMENT_DECL:
1624|		    case XML_ATTRIBUTE_DECL:
1625|		    case XML_ENTITY_DECL:
1626|			continue; /* for */
1627|		}
1628|		if (last == NULL)
1629|		    list = last = xmlCopyNode(set->nodeTab[i], 1);
1630|		else {
1631|		    xmlAddNextSibling(last, xmlCopyNode(set->nodeTab[i], 1));
1632|		    if (last->next != NULL)
1633|			last = last->next;
1634|		}
1635|	    }
1636|	    break;
1637|	}
1638|	case XPATH_LOCATIONSET: {
1639|	    xmlLocationSetPtr set = (xmlLocationSetPtr) obj->user;
1640|	    if (set == NULL)
1641|		return(NULL);
1642|	    for (i = 0;i < set->locNr;i++) {
1643|		if (last == NULL)
1644|		    list = last = xmlXPtrBuildNodeList(set->locTab[i]);
1645|		else
1646|		    xmlAddNextSibling(last,
1647|			    xmlXPtrBuildNodeList(set->locTab[i]));
1648|		if (last != NULL) {
1649|		    while (last->next != NULL)
1650|			last = last->next;
1651|		}
1652|	    }
1653|	    break;
1654|	}
1655|	case XPATH_RANGE:
1656|	    return(xmlXPtrBuildRangeNodeList(obj));
1657|	case XPATH_POINT:
1658|	    return(xmlCopyNode(obj->user, 0));
1659|	default:
1660|	    break;
1661|    }
1662|    return(list);
1663|}
