2638|/**
2639| * xmlXPtrStringRangeFunction:
2640| * @ctxt:  the XPointer Parser context
2641| * @nargs:  the number of args
2642| *
2643| * Function implementing the string-range() function
2644| * range as described in 5.4.2
2645| *
2646| * ------------------------------
2647| * [Definition: For each location in the location-set argument,
2648| * string-range returns a set of string ranges, a set of substrings in a
2649| * string. Specifically, the string-value of the location is searched for
2650| * substrings that match the string argument, and the resulting location-set
2651| * will contain a range location for each non-overlapping match.]
2652| * An empty string is considered to match before each character of the
2653| * string-value and after the final character. Whitespace in a string
2654| * is matched literally, with no normalization except that provided by
2655| * XML for line ends. The third argument gives the position of the first
2656| * character to be in the resulting range, relative to the start of the
2657| * match. The default value is 1, which makes the range start immediately
2658| * before the first character of the matched string. The fourth argument
2659| * gives the number of characters in the range; the default is that the
2660| * range extends to the end of the matched string.
2661| *
2662| * Element boundaries, as well as entire embedded nodes such as processing
2663| * instructions and comments, are ignored as defined in [XPath].
2664| *
2665| * If the string in the second argument is not found in the string-value
2666| * of the location, or if a value in the third or fourth argument indicates
2667| * a string that is beyond the beginning or end of the document, the
2668| * expression fails.
2669| *
2670| * The points of the range-locations in the returned location-set will
2671| * all be character points.
2672| * ------------------------------
2673| */
2674|static void
2675|xmlXPtrStringRangeFunction(xmlXPathParserContextPtr ctxt, int nargs) {
2676|    int i, startindex, endindex = 0, fendindex;
2677|    xmlNodePtr start, end = 0, fend;
2678|    xmlXPathObjectPtr set = NULL;
2679|    xmlLocationSetPtr oldset;
2680|    xmlLocationSetPtr newset = NULL;
2681|    xmlXPathObjectPtr string = NULL;
2682|    xmlXPathObjectPtr position = NULL;
2683|    xmlXPathObjectPtr number = NULL;
2684|    int found, pos = 0, num = 0;
2685|
2686|    /*
2687|     * Grab the arguments
2688|     */
2689|    if ((nargs < 2) || (nargs > 4))
2690|	XP_ERROR(XPATH_INVALID_ARITY);
2691|
2692|    if (nargs >= 4) {
2693|        if ((ctxt->value == NULL) || (ctxt->value->type != XPATH_NUMBER)) {
2694|            xmlXPathErr(ctxt, XPATH_INVALID_TYPE);
2695|            goto error;
2696|        }
2697|	number = valuePop(ctxt);
2698|	if (number != NULL)
2699|	    num = (int) number->floatval;
2700|    }
2701|    if (nargs >= 3) {
2702|        if ((ctxt->value == NULL) || (ctxt->value->type != XPATH_NUMBER)) {
2703|            xmlXPathErr(ctxt, XPATH_INVALID_TYPE);
2704|            goto error;
2705|        }
2706|	position = valuePop(ctxt);
2707|	if (position != NULL)
2708|	    pos = (int) position->floatval;
2709|    }
2710|    if ((ctxt->value == NULL) || (ctxt->value->type != XPATH_STRING)) {
2711|        xmlXPathErr(ctxt, XPATH_INVALID_TYPE);
2712|        goto error;
2713|    }
2714|    string = valuePop(ctxt);
2715|    if ((ctxt->value == NULL) ||
2716|	((ctxt->value->type != XPATH_LOCATIONSET) &&
2717|	 (ctxt->value->type != XPATH_NODESET))) {
2718|        xmlXPathErr(ctxt, XPATH_INVALID_TYPE);
2719|        goto error;
2720|    }
2721|    set = valuePop(ctxt);
2722|    newset = xmlXPtrLocationSetCreate(NULL);
2723|    if (newset == NULL) {
2724|        xmlXPathErr(ctxt, XPATH_MEMORY_ERROR);
2725|        goto error;
2726|    }
2727|    if (set->nodesetval == NULL) {
2728|        goto error;
2729|    }
2730|    if (set->type == XPATH_NODESET) {
2731|	xmlXPathObjectPtr tmp;
2732|
2733|	/*
2734|	 * First convert to a location set
2735|	 */
2736|	tmp = xmlXPtrNewLocationSetNodeSet(set->nodesetval);
2737|	xmlXPathFreeObject(set);
2738|        set = NULL;
2739|	if (tmp == NULL) {
2740|            xmlXPathErr(ctxt, XPATH_MEMORY_ERROR);
2741|            goto error;
2742|        }
2743|	set = tmp;
2744|    }
2745|    oldset = (xmlLocationSetPtr) set->user;
2746|
2747|    /*
2748|     * The loop is to search for each element in the location set
2749|     * the list of location set corresponding to that search
2750|     */
2751|    for (i = 0;i < oldset->locNr;i++) {
2752|
2753|	xmlXPtrGetStartPoint(oldset->locTab[i], &start, &startindex);
2754|	xmlXPtrGetEndPoint(oldset->locTab[i], &end, &endindex);
2755|	xmlXPtrAdvanceChar(&start, &startindex, 0);
2756|	xmlXPtrGetLastChar(&end, &endindex);
2757|
2758|	do {
2759|            fend = end;
2760|            fendindex = endindex;
2761|	    found = xmlXPtrSearchString(string->stringval, &start, &startindex,
2762|		                        &fend, &fendindex);
2763|	    if (found == 1) {
2764|		if (position == NULL) {
2765|		    xmlXPtrLocationSetAdd(newset,
2766|			 xmlXPtrNewRange(start, startindex, fend, fendindex));
2767|		} else if (xmlXPtrAdvanceChar(&start, &startindex,
2768|			                      pos - 1) == 0) {
2769|		    if ((number != NULL) && (num > 0)) {
2770|			int rindx;
2771|			xmlNodePtr rend;
2772|			rend = start;
2773|			rindx = startindex - 1;
2774|			if (xmlXPtrAdvanceChar(&rend, &rindx,
2775|				               num) == 0) {
2776|			    xmlXPtrLocationSetAdd(newset,
2777|					xmlXPtrNewRange(start, startindex,
2778|							rend, rindx));
2779|			}
2780|		    } else if ((number != NULL) && (num <= 0)) {
2781|			xmlXPtrLocationSetAdd(newset,
2782|				    xmlXPtrNewRange(start, startindex,
2783|						    start, startindex));
2784|		    } else {
2785|			xmlXPtrLocationSetAdd(newset,
2786|				    xmlXPtrNewRange(start, startindex,
2787|						    fend, fendindex));
2788|		    }
2789|		}
2790|		start = fend;
2791|		startindex = fendindex;
2792|		if (string->stringval[0] == 0)
2793|		    startindex++;
2794|	    }
2795|	} while (found == 1);
2796|    }
2797|
2798|    /*
2799|     * Save the new value and cleanup
2800|     */
2801|error:
2802|    if (newset != NULL)
2803|        valuePush(ctxt, xmlXPtrWrapLocationSet(newset));
2804|    xmlXPathFreeObject(set);
2805|    xmlXPathFreeObject(string);
2806|    if (position) xmlXPathFreeObject(position);
2807|    if (number) xmlXPathFreeObject(number);
2808|}
