2810|/**
2811| * xmlXPtrEvalRangePredicate:
2812| * @ctxt:  the XPointer Parser context
2813| *
2814| *  [8]   Predicate ::=   '[' PredicateExpr ']'
2815| *  [9]   PredicateExpr ::=   Expr
2816| *
2817| * Evaluate a predicate as in xmlXPathEvalPredicate() but for
2818| * a Location Set instead of a node set
2819| */
2820|void
2821|xmlXPtrEvalRangePredicate(xmlXPathParserContextPtr ctxt) {
2822|    const xmlChar *cur;
2823|    xmlXPathObjectPtr res;
2824|    xmlXPathObjectPtr obj, tmp;
2825|    xmlLocationSetPtr newset = NULL;
2826|    xmlLocationSetPtr oldset;
2827|    int i;
2828|
2829|    if (ctxt == NULL) return;
2830|
2831|    SKIP_BLANKS;
2832|    if (CUR != '[') {
2833|	XP_ERROR(XPATH_INVALID_PREDICATE_ERROR);
2834|    }
2835|    NEXT;
2836|    SKIP_BLANKS;
2837|
2838|    /*
2839|     * Extract the old set, and then evaluate the result of the
2840|     * expression for all the element in the set. use it to grow
2841|     * up a new set.
2842|     */
2843|    CHECK_TYPE(XPATH_LOCATIONSET);
2844|    obj = valuePop(ctxt);
2845|    oldset = obj->user;
2846|    ctxt->context->node = NULL;
2847|
2848|    if ((oldset == NULL) || (oldset->locNr == 0)) {
2849|	ctxt->context->contextSize = 0;
2850|	ctxt->context->proximityPosition = 0;
2851|	xmlXPathEvalExpr(ctxt);
2852|	res = valuePop(ctxt);
2853|	if (res != NULL)
2854|	    xmlXPathFreeObject(res);
2855|	valuePush(ctxt, obj);
2856|	CHECK_ERROR;
2857|    } else {
2858|	/*
2859|	 * Save the expression pointer since we will have to evaluate
2860|	 * it multiple times. Initialize the new set.
2861|	 */
2862|        cur = ctxt->cur;
2863|	newset = xmlXPtrLocationSetCreate(NULL);
2864|
2865|        for (i = 0; i < oldset->locNr; i++) {
2866|	    ctxt->cur = cur;
2867|
2868|	    /*
2869|	     * Run the evaluation with a node list made of a single item
2870|	     * in the nodeset.
2871|	     */
2872|	    ctxt->context->node = oldset->locTab[i]->user;
2873|	    tmp = xmlXPathNewNodeSet(ctxt->context->node);
2874|	    valuePush(ctxt, tmp);
2875|	    ctxt->context->contextSize = oldset->locNr;
2876|	    ctxt->context->proximityPosition = i + 1;
2877|
2878|	    xmlXPathEvalExpr(ctxt);
2879|	    CHECK_ERROR;
2880|
2881|	    /*
2882|	     * The result of the evaluation need to be tested to
2883|	     * decided whether the filter succeeded or not
2884|	     */
2885|	    res = valuePop(ctxt);
2886|	    if (xmlXPathEvaluatePredicateResult(ctxt, res)) {
2887|	        xmlXPtrLocationSetAdd(newset,
2888|			xmlXPathObjectCopy(oldset->locTab[i]));
2889|	    }
2890|
2891|	    /*
2892|	     * Cleanup
2893|	     */
2894|	    if (res != NULL)
2895|		xmlXPathFreeObject(res);
2896|	    if (ctxt->value == tmp) {
2897|		res = valuePop(ctxt);
2898|		xmlXPathFreeObject(res);
2899|	    }
2900|
2901|	    ctxt->context->node = NULL;
2902|	}
2903|
2904|	/*
2905|	 * The result is used as the new evaluation set.
2906|	 */
2907|	xmlXPathFreeObject(obj);
2908|	ctxt->context->node = NULL;
2909|	ctxt->context->contextSize = -1;
2910|	ctxt->context->proximityPosition = -1;
2911|	valuePush(ctxt, xmlXPtrWrapLocationSet(newset));
2912|    }
2913|    if (CUR != ']') {
2914|	XP_ERROR(XPATH_INVALID_PREDICATE_ERROR);
2915|    }
2916|
2917|    NEXT;
2918|    SKIP_BLANKS;
2919|}
